// Standing offers of the demo specialists, signed offline with each specialist's offer key.
// Generated by scripts/sign-offers.ts — do not edit by hand.
import type { SignedOffer, SignedOffer2 } from '../core/offer';
import data from './offers.json';

/** The v2 form of an offer: paid into a hash-lock contract; the full file is public but sealed (scripts/sign-offers-v2.ts). */
export type OfferEntry2 = {
  signed: SignedOffer2;
  offerHashHex: string;
  payToLockingHex: string;
  /** The sealed full file, a static path on this site. */
  sealed: string;
  /** The cover's light copy, sealed under the same key (display only, not what the offer's fingerprint is of). */
  sealedLight?: string;
};

export type OfferEntry = {
  signed: SignedOffer;
  /** Full file name under /files/ (v1: served only after payment, through /full/<key>). */
  file: string;
  /** Public preview: an image or audio URL, or the first sentence per requested language. */
  preview: string | Record<string, string>;
  v2?: OfferEntry2;
};

export type OfferBook = Record<'mainnet' | 'chipnet', Record<string, OfferEntry>>;

export const OFFERS = data as unknown as OfferBook;
